// 先写测试：明确边界与异常，再让 AI 实现
class CouponServiceTest {
    @Test void 满减券_满足门槛时扣减() {
        assertEquals(new BigDecimal("80.00"), svc.apply(new BigDecimal("100.00"), coupon(100, 20)));
    }
    @Test void 满减券_未达门槛不扣减() {
        assertEquals(new BigDecimal("99.99"), svc.apply(new BigDecimal("99.99"), coupon(100, 20)));
    }
    @Test void 已过期券_抛出异常() {
        assertThrows(CouponExpiredException.class, () -> svc.apply(new BigDecimal("200"), expiredCoupon()));
    }
    @Test void 金额不能为负() {
        assertEquals(BigDecimal.ZERO.setScale(2), svc.apply(new BigDecimal("10.00"), coupon(0, 20)));
    }
}
